using Berbergelsin.Api.Dtos;using Berbergelsin.Api.Services;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.RateLimiting;
namespace Berbergelsin.Api.Controllers;
[ApiController,Route("api/locations"),Authorize,EnableRateLimiting("address-search")]
public sealed class LocationsController(IAddressSearchProvider provider):ControllerBase{
 [HttpGet("address-suggestions")]public async Task<IActionResult> Suggestions([FromQuery]AddressAutocompleteRequest x,CancellationToken ct){if(!Guid.TryParse(x.SessionToken,out _))ModelState.AddModelError(nameof(x.SessionToken),"UUID required");if(!ModelState.IsValid)return ValidationProblem(ModelState);try{return Ok(await provider.AutocompleteAsync(x,ct));}catch(AddressProviderException e){return Error(e);}}
 [HttpGet("places/{placeId}")]public async Task<IActionResult> Place(string placeId,[FromQuery]string sessionToken,CancellationToken ct){if(placeId.Length>512||!Guid.TryParse(sessionToken,out _))return BadRequest(new AddressErrorDto("address_not_found"));try{var x=await provider.ResolvePlaceAsync(placeId,sessionToken,ct);return x==null?NotFound(new AddressErrorDto("address_not_found")):string.IsNullOrWhiteSpace(x.Province)||string.IsNullOrWhiteSpace(x.District)?StatusCode(422,new AddressErrorDto("address_incomplete")):Ok(x);}catch(AddressProviderException e){return Error(e);}}
 ObjectResult Error(AddressProviderException e)=>e.Failure switch{AddressProviderFailure.Unavailable=>StatusCode(503,new AddressErrorDto("address_search_unavailable")),AddressProviderFailure.RateLimited=>StatusCode(429,new AddressErrorDto("address_search_rate_limited")),_=>StatusCode(502,new AddressErrorDto("address_provider_error"))};}